// Verifica se tem sessao salva no Static Data
const staticData = $getWorkflowStaticData('global');
const cookies = staticData.cookies || [];
const localStorage = staticData.localStorage || {};
const ultimoLogin = staticData.ultimoLogin || null;

// Sessao valida se tem cookies e login foi ha menos de 1 hora
const agora = Date.now();
const umaHora = 60 * 60 * 1000;
const sessaoValida = cookies.length > 0 && ultimoLogin && (agora - new Date(ultimoLogin).getTime()) < umaHora;

return [{
  json: {
    temSessao: sessaoValida,
    cookies: cookies,
    localStorage: localStorage,
    ultimoLogin: ultimoLogin
  }
}];

