// Salva sessao no Static Data para proxima execucao
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

// Se sessao expirada, limpa os dados salvos
if (input.sessaoExpirada) {
  staticData.cookies = [];
  staticData.localStorage = {};
  staticData.ultimoLogin = null;
} else if (input.success && input.cookies) {
  staticData.cookies = input.cookies;
  staticData.localStorage = input.localStorage;
  staticData.ultimoLogin = new Date().toISOString();
}

return [{
  json: {
    success: input.success,
    error: input.error || null,
    log: input.log || [],
    url: input.url,
    sessaoSalva: input.success && !input.sessaoExpirada
  }
}];

